/// <summary>
/// The Extension of PurchCopying class.
/// </summary>
[ExtensionOf(classStr(PurchCopying))]
final class METPurchCopying_Extension
{
    public RefRecId selectedLastRecord;
    public RefTableId selectedRecordTableId;
}

Method.Source:
    /// <summary>
    /// Copies from a purchase order.
    /// </summary>
    /// <param name = "_tmpFrmVirtualHeader">A <c>TmpFrmVirtual</c> record, which is the source record.</param>
    /// <returns>A <c>PurchTable</c> record.</returns>
    protected PurchTable copyFromPurchTable(TmpFrmVirtual _tmpFrmVirtualHeader)
    {
        PurchTable metFromTransLocal = PurchTable::findRecId(tmpFrmVirtualHeader.RecordNo);
        METPurchTable metPurchTableFrom = METPurchTable::findByPurchTable(metFromTransLocal.RecId);
        METPurchTable metPurchTableTo = METPurchTable::findByPurchTable(purchTable.RecId, true);
        
        next copyFromPurchTable(_tmpFrmVirtualHeader); 

        if (metPurchTableTo)
        {
            metPurchTableTo.POSubSource = metPurchTableFrom.POSubSource;
            metPurchTableTo.update();
        }        

        return metFromTransLocal;
    }

    /// <summary>
    /// Copy header info to destination
    /// </summary>
    void copyHeader()
    {
        this.deleteHeaderTable();

        next copyHeader();

        this.updateDestinationPurchItemBuyerGroup();
        
    }

/// <summary>
/// Delete header info from tmp table 
/// </summary>
void deleteHeaderTable()
{
    if (copyPrecisely && !tmpFrmVirtualHeader.Id)
    {
        selectedRecordTableId = tmpFrmVirtualHeader.TableNum;
        selectedLastRecord = tmpFrmVirtualHeader.RecordNo;
        ttsbegin;
        tmpFrmVirtualHeader.selectforupdate(true);
        tmpFrmVirtualHeader.delete();
        ttscommit;
    }
}

    /// <summary>
    /// Update destination PO itembuyer group from last selected PO
    /// </summary>
    void updateDestinationPurchItemBuyerGroup()
    {
        if (copyPrecisely && tmpFrmVirtualHeader.recid == 0)
        
        {
            ItemBuyerGroupId purchTableItemBuyerGroup;

            switch(selectedRecordTableId)
            {
                case tableNum(PurchTable):
                    purchTableItemBuyerGroup = PurchTable::findRecId(selectedLastRecord).ItemBuyerGroupId;
                    break;
                case tableNum(VendInvoiceJour)   :
                    purchTableItemBuyerGroup = PurchTable::find(VendInvoiceJour::findRecId(selectedLastRecord).PurchId).ItemBuyerGroupId;
                    break;
                case tableNum(VendPackingSlipJour)  :
                    purchTableItemBuyerGroup = PurchTable::find(VendPackingSlipJour::findRecId(selectedLastRecord).PurchId).ItemBuyerGroupId;
                    break;
                case tableNum(VendPurchOrderJour)   :
                    purchTableItemBuyerGroup = VendPurchOrderJour::findRecId(tmpFrmVirtualHeader.RecordNo).purchTable().ItemBuyerGroupId;
                    break;
            }

            if (purchTable && purchTableItemBuyerGroup)
            {
                purchTable.ItemBuyerGroupId = purchTableItemBuyerGroup;
                purchTable.update();
            }
        }
        
        //Bug_242895_CB219_POBuyerGroupFixes
        if (copyPrecisely && tmpFrmVirtualHeader.recid != 0 && tmpFrmVirtualHeader.TableNum == tableNum(PurchTable))
        {
            ItemBuyerGroupId purchTableItemBuyerGroup;

            purchTableItemBuyerGroup = PurchTable::findRecId(tmpFrmVirtualHeader.RecordNo).ItemBuyerGroupId;

            if (purchTable && purchTableItemBuyerGroup)
            {
                purchTable.ItemBuyerGroupId = purchTableItemBuyerGroup;
                purchTable.update();
            }
        }
    }
